20251218221836	{"-- Create role enum\nCREATE TYPE public.app_role AS ENUM ('admin', 'gerente', 'revendedor', 'visualizador');\n\n-- Create profiles table\nCREATE TABLE public.profiles (\n  id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,\n  full_name TEXT NOT NULL,\n  email TEXT NOT NULL,\n  phone TEXT,\n  avatar_url TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Create user_roles table\nCREATE TABLE public.user_roles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,\n  role app_role NOT NULL DEFAULT 'visualizador',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE (user_id, role)\n);\n\n-- Create stores table\nCREATE TABLE public.stores (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name TEXT NOT NULL,\n  address TEXT,\n  city TEXT,\n  state TEXT,\n  phone TEXT,\n  email TEXT,\n  manager_id UUID REFERENCES auth.users(id),\n  is_active BOOLEAN NOT NULL DEFAULT true,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Create resellers table\nCREATE TABLE public.resellers (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID REFERENCES auth.users(id),\n  store_id UUID REFERENCES public.stores(id) ON DELETE SET NULL,\n  full_name TEXT NOT NULL,\n  cpf TEXT UNIQUE,\n  phone TEXT,\n  email TEXT,\n  commission_rate DECIMAL(5,2) DEFAULT 0,\n  is_active BOOLEAN NOT NULL DEFAULT true,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Create vehicles table\nCREATE TABLE public.vehicles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  store_id UUID REFERENCES public.stores(id) ON DELETE SET NULL,\n  brand TEXT NOT NULL,\n  model TEXT NOT NULL,\n  year INTEGER NOT NULL,\n  color TEXT,\n  plate TEXT UNIQUE,\n  chassis TEXT UNIQUE,\n  renavam TEXT,\n  mileage INTEGER DEFAULT 0,\n  fuel_type TEXT,\n  transmission TEXT,\n  purchase_price DECIMAL(12,2),\n  sale_price DECIMAL(12,2),\n  status TEXT NOT NULL DEFAULT 'disponivel' CHECK (status IN ('disponivel', 'reservado', 'vendido')),\n  images TEXT[],\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Create contracts table\nCREATE TABLE public.contracts (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  contract_number TEXT UNIQUE NOT NULL,\n  vehicle_id UUID REFERENCES public.vehicles(id) ON DELETE RESTRICT NOT NULL,\n  reseller_id UUID REFERENCES public.resellers(id) ON DELETE RESTRICT NOT NULL,\n  store_id UUID REFERENCES public.stores(id) ON DELETE RESTRICT NOT NULL,\n  buyer_name TEXT NOT NULL,\n  buyer_cpf TEXT NOT NULL,\n  buyer_phone TEXT,\n  buyer_email TEXT,\n  buyer_address TEXT,\n  sale_price DECIMAL(12,2) NOT NULL,\n  down_payment DECIMAL(12,2) DEFAULT 0,\n  installments INTEGER DEFAULT 1,\n  installment_value DECIMAL(12,2),\n  status TEXT NOT NULL DEFAULT 'pendente' CHECK (status IN ('pendente', 'assinado', 'cancelado', 'concluido')),\n  signed_at TIMESTAMPTZ,\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Create payments table\nCREATE TABLE public.payments (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  contract_id UUID REFERENCES public.contracts(id) ON DELETE CASCADE NOT NULL,\n  reseller_id UUID REFERENCES public.resellers(id) ON DELETE RESTRICT NOT NULL,\n  amount DECIMAL(12,2) NOT NULL,\n  payment_date DATE NOT NULL,\n  payment_method TEXT,\n  reference TEXT,\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Create activity_logs table for security\nCREATE TABLE public.activity_logs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL,\n  action TEXT NOT NULL,\n  entity_type TEXT,\n  entity_id UUID,\n  details JSONB,\n  ip_address TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on all tables\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.stores ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.resellers ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contracts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.payments ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.activity_logs ENABLE ROW LEVEL SECURITY;\n\n-- Security definer function to check roles\nCREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role app_role)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.user_roles\n    WHERE user_id = _user_id\n      AND role = _role\n  )\n$$;\n\n-- Function to check if user has any elevated role\nCREATE OR REPLACE FUNCTION public.has_elevated_access(_user_id UUID)\nRETURNS BOOLEAN\nLANGUAGE SQL\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.user_roles\n    WHERE user_id = _user_id\n      AND role IN ('admin', 'gerente')\n  )\n$$;\n\n-- Function to get user's store (for resellers)\nCREATE OR REPLACE FUNCTION public.get_user_store_id(_user_id UUID)\nRETURNS UUID\nLANGUAGE SQL\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT store_id\n  FROM public.resellers\n  WHERE user_id = _user_id\n  LIMIT 1\n$$;\n\n-- Profiles policies\nCREATE POLICY \\"Users can view own profile\\"\n  ON public.profiles FOR SELECT\n  TO authenticated\n  USING (id = auth.uid() OR public.has_role(auth.uid(), 'admin'));\n\nCREATE POLICY \\"Users can update own profile\\"\n  ON public.profiles FOR UPDATE\n  TO authenticated\n  USING (id = auth.uid());\n\nCREATE POLICY \\"Admins can insert profiles\\"\n  ON public.profiles FOR INSERT\n  TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'admin'));\n\n-- User roles policies (only admins can manage)\nCREATE POLICY \\"Admins can view all roles\\"\n  ON public.user_roles FOR SELECT\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'admin') OR user_id = auth.uid());\n\nCREATE POLICY \\"Admins can insert roles\\"\n  ON public.user_roles FOR INSERT\n  TO authenticated\n  WITH CHECK (public.has_role(auth.uid(), 'admin'));\n\nCREATE POLICY \\"Admins can update roles\\"\n  ON public.user_roles FOR UPDATE\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'admin'));\n\nCREATE POLICY \\"Admins can delete roles\\"\n  ON public.user_roles FOR DELETE\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'admin'));\n\n-- Stores policies\nCREATE POLICY \\"Authenticated users can view active stores\\"\n  ON public.stores FOR SELECT\n  TO authenticated\n  USING (is_active = true OR public.has_elevated_access(auth.uid()));\n\nCREATE POLICY \\"Admins can manage stores\\"\n  ON public.stores FOR ALL\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'admin'))\n  WITH CHECK (public.has_role(auth.uid(), 'admin'));\n\n-- Resellers policies\nCREATE POLICY \\"View resellers based on role\\"\n  ON public.resellers FOR SELECT\n  TO authenticated\n  USING (\n    public.has_elevated_access(auth.uid())\n    OR user_id = auth.uid()\n    OR store_id = public.get_user_store_id(auth.uid())\n  );\n\nCREATE POLICY \\"Admins and managers can manage resellers\\"\n  ON public.resellers FOR ALL\n  TO authenticated\n  USING (public.has_elevated_access(auth.uid()))\n  WITH CHECK (public.has_elevated_access(auth.uid()));\n\n-- Vehicles policies\nCREATE POLICY \\"View vehicles based on role\\"\n  ON public.vehicles FOR SELECT\n  TO authenticated\n  USING (\n    public.has_elevated_access(auth.uid())\n    OR store_id = public.get_user_store_id(auth.uid())\n  );\n\nCREATE POLICY \\"Admins and managers can manage vehicles\\"\n  ON public.vehicles FOR ALL\n  TO authenticated\n  USING (public.has_elevated_access(auth.uid()))\n  WITH CHECK (public.has_elevated_access(auth.uid()));\n\n-- Contracts policies\nCREATE POLICY \\"View contracts based on role\\"\n  ON public.contracts FOR SELECT\n  TO authenticated\n  USING (\n    public.has_elevated_access(auth.uid())\n    OR reseller_id IN (SELECT id FROM public.resellers WHERE user_id = auth.uid())\n    OR store_id = public.get_user_store_id(auth.uid())\n  );\n\nCREATE POLICY \\"Create contracts\\"\n  ON public.contracts FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    public.has_elevated_access(auth.uid())\n    OR reseller_id IN (SELECT id FROM public.resellers WHERE user_id = auth.uid())\n  );\n\nCREATE POLICY \\"Admins can manage contracts\\"\n  ON public.contracts FOR UPDATE\n  TO authenticated\n  USING (public.has_elevated_access(auth.uid()));\n\n-- Payments policies\nCREATE POLICY \\"View payments based on role\\"\n  ON public.payments FOR SELECT\n  TO authenticated\n  USING (\n    public.has_elevated_access(auth.uid())\n    OR reseller_id IN (SELECT id FROM public.resellers WHERE user_id = auth.uid())\n  );\n\nCREATE POLICY \\"Admins can manage payments\\"\n  ON public.payments FOR ALL\n  TO authenticated\n  USING (public.has_elevated_access(auth.uid()))\n  WITH CHECK (public.has_elevated_access(auth.uid()));\n\n-- Activity logs policies\nCREATE POLICY \\"Admins can view all logs\\"\n  ON public.activity_logs FOR SELECT\n  TO authenticated\n  USING (public.has_role(auth.uid(), 'admin'));\n\nCREATE POLICY \\"System can insert logs\\"\n  ON public.activity_logs FOR INSERT\n  TO authenticated\n  WITH CHECK (true);\n\n-- Trigger to create profile on user signup\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  INSERT INTO public.profiles (id, full_name, email)\n  VALUES (\n    NEW.id,\n    COALESCE(NEW.raw_user_meta_data ->> 'full_name', NEW.email),\n    NEW.email\n  );\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();\n\n-- Trigger to update updated_at timestamp\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nAS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER update_profiles_updated_at\n  BEFORE UPDATE ON public.profiles\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER update_stores_updated_at\n  BEFORE UPDATE ON public.stores\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER update_resellers_updated_at\n  BEFORE UPDATE ON public.resellers\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER update_vehicles_updated_at\n  BEFORE UPDATE ON public.vehicles\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER update_contracts_updated_at\n  BEFORE UPDATE ON public.contracts\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();"}		apikey@lovable.dev	\N	\N
20251218221924	{"-- Fix function search path for update_updated_at_column\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSET search_path = public\nAS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$;"}		apikey@lovable.dev	\N	\N
20251219204836	{"-- Create enum for contract template types\nCREATE TYPE public.contract_template_type AS ENUM ('venda_carro', 'venda_moto', 'repasse', 'generico');\n\n-- Create table for contract templates/models\nCREATE TABLE public.contract_templates (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  name TEXT NOT NULL,\n  template_type contract_template_type NOT NULL,\n  is_active BOOLEAN NOT NULL DEFAULT false,\n  version INTEGER NOT NULL DEFAULT 1,\n  \n  -- Content blocks\n  header_content TEXT,\n  body_content TEXT NOT NULL,\n  clauses_content TEXT,\n  signature_content TEXT,\n  \n  -- Fixed clauses that cannot be removed\n  fixed_clauses TEXT[] DEFAULT ARRAY[]::TEXT[],\n  \n  -- Store reference (null = available to all stores)\n  store_id UUID REFERENCES public.stores(id) ON DELETE SET NULL,\n  \n  -- Audit fields\n  created_by UUID REFERENCES auth.users(id),\n  updated_by UUID REFERENCES auth.users(id),\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  \n  -- Ensure unique name per type\n  UNIQUE(name, template_type)\n);\n\n-- Enable RLS\nALTER TABLE public.contract_templates ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies\nCREATE POLICY \\"Anyone can view active templates\\"\nON public.contract_templates\nFOR SELECT\nTO authenticated\nUSING (is_active = true OR public.has_elevated_access(auth.uid()));\n\nCREATE POLICY \\"Elevated users can create templates\\"\nON public.contract_templates\nFOR INSERT\nTO authenticated\nWITH CHECK (public.has_elevated_access(auth.uid()));\n\nCREATE POLICY \\"Elevated users can update templates\\"\nON public.contract_templates\nFOR UPDATE\nTO authenticated\nUSING (public.has_elevated_access(auth.uid()));\n\nCREATE POLICY \\"Elevated users can delete templates\\"\nON public.contract_templates\nFOR DELETE\nTO authenticated\nUSING (public.has_elevated_access(auth.uid()));\n\n-- Create trigger for updated_at\nCREATE TRIGGER update_contract_templates_updated_at\nBEFORE UPDATE ON public.contract_templates\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Add signed_contract_url column to contracts table for uploaded signed contracts\nALTER TABLE public.contracts \nADD COLUMN IF NOT EXISTS signed_contract_url TEXT,\nADD COLUMN IF NOT EXISTS template_id UUID REFERENCES public.contract_templates(id),\nADD COLUMN IF NOT EXISTS contract_type TEXT DEFAULT 'venda';\n\n-- Create storage bucket for signed contracts\nINSERT INTO storage.buckets (id, name, public)\nVALUES ('signed-contracts', 'signed-contracts', false)\nON CONFLICT (id) DO NOTHING;\n\n-- Storage policies for signed contracts\nCREATE POLICY \\"Authenticated users can upload signed contracts\\"\nON storage.objects\nFOR INSERT\nTO authenticated\nWITH CHECK (bucket_id = 'signed-contracts');\n\nCREATE POLICY \\"Authenticated users can view signed contracts\\"\nON storage.objects\nFOR SELECT\nTO authenticated\nUSING (bucket_id = 'signed-contracts');\n\n-- Insert default contract templates\nINSERT INTO public.contract_templates (name, template_type, is_active, header_content, body_content, clauses_content, signature_content, fixed_clauses) VALUES\n(\n  'Contrato de Venda - Carro',\n  'venda_carro',\n  true,\n  'CONTRATO PARTICULAR DE COMPRA E VENDA DE VEÍCULO AUTOMOTOR',\n  E'Pelo presente instrumento particular, de um lado {{LOJA_RAZAO_SOCIAL}}, inscrita no CNPJ sob nº {{LOJA_CNPJ}}, com sede em {{LOJA_ENDERECO}}, doravante denominada VENDEDORA, e de outro lado {{CLIENTE_NOME}}, portador(a) do CPF nº {{CLIENTE_CPF}}, residente em {{CLIENTE_ENDERECO}}, telefone {{CLIENTE_TELEFONE}}, e-mail {{CLIENTE_EMAIL}}, doravante denominado(a) COMPRADOR(A), têm entre si justo e contratado a compra e venda do veículo abaixo descrito:\\\\n\\\\nVEÍCULO: {{VEICULO_MARCA}} {{VEICULO_MODELO}}\\\\nANO: {{VEICULO_ANO}}\\\\nCOR: {{VEICULO_COR}}\\\\nCHASSI: {{VEICULO_CHASSI}}\\\\nPLACA: {{VEICULO_PLACA}}\\\\nRENAVAM: {{VEICULO_RENAVAM}}\\\\n\\\\nVALOR DA VENDA: {{VALOR_TOTAL}}\\\\nENTRADA: {{VALOR_ENTRADA}}\\\\nFORMA DE PAGAMENTO: {{FORMA_PAGAMENTO}}\\\\nPARCELAS: {{PARCELAS}}',\n  E'CLÁUSULA PRIMEIRA: A VENDEDORA vende e transfere ao COMPRADOR o veículo acima descrito, livre e desembaraçado de quaisquer ônus.\\\\n\\\\nCLÁUSULA SEGUNDA: O COMPRADOR declara ter examinado o veículo e estar de acordo com seu estado de conservação.\\\\n\\\\nCLÁUSULA TERCEIRA: A transferência de propriedade será realizada após a quitação total do valor acordado.\\\\n\\\\nCLÁUSULA QUARTA: As partes elegem o foro da comarca de {{LOJA_CIDADE}} para dirimir quaisquer dúvidas oriundas deste contrato.',\n  E'{{LOJA_CIDADE}}, {{DATA_CONTRATO}}\\\\n\\\\n\\\\n_______________________________\\\\nVENDEDORA: {{LOJA_RAZAO_SOCIAL}}\\\\n\\\\n\\\\n_______________________________\\\\nCOMPRADOR(A): {{CLIENTE_NOME}}\\\\nCPF: {{CLIENTE_CPF}}',\n  ARRAY[]::TEXT[]\n),\n(\n  'Contrato de Venda - Moto',\n  'venda_moto',\n  true,\n  'CONTRATO PARTICULAR DE COMPRA E VENDA DE MOTOCICLETA',\n  E'Pelo presente instrumento particular, de um lado {{LOJA_RAZAO_SOCIAL}}, inscrita no CNPJ sob nº {{LOJA_CNPJ}}, com sede em {{LOJA_ENDERECO}}, doravante denominada VENDEDORA, e de outro lado {{CLIENTE_NOME}}, portador(a) do CPF nº {{CLIENTE_CPF}}, residente em {{CLIENTE_ENDERECO}}, telefone {{CLIENTE_TELEFONE}}, e-mail {{CLIENTE_EMAIL}}, doravante denominado(a) COMPRADOR(A), têm entre si justo e contratado a compra e venda da motocicleta abaixo descrita:\\\\n\\\\nMOTOCICLETA: {{VEICULO_MARCA}} {{VEICULO_MODELO}}\\\\nANO: {{VEICULO_ANO}}\\\\nCOR: {{VEICULO_COR}}\\\\nCHASSI: {{VEICULO_CHASSI}}\\\\nPLACA: {{VEICULO_PLACA}}\\\\nRENAVAM: {{VEICULO_RENAVAM}}\\\\n\\\\nVALOR DA VENDA: {{VALOR_TOTAL}}\\\\nENTRADA: {{VALOR_ENTRADA}}\\\\nFORMA DE PAGAMENTO: {{FORMA_PAGAMENTO}}\\\\nPARCELAS: {{PARCELAS}}',\n  E'CLÁUSULA PRIMEIRA: A VENDEDORA vende e transfere ao COMPRADOR a motocicleta acima descrita, livre e desembaraçada de quaisquer ônus.\\\\n\\\\nCLÁUSULA SEGUNDA: O COMPRADOR declara ter examinado a motocicleta e estar de acordo com seu estado de conservação.\\\\n\\\\nCLÁUSULA TERCEIRA: A transferência de propriedade será realizada após a quitação total do valor acordado.\\\\n\\\\nCLÁUSULA QUARTA: O EMPLACAMENTO É DE RESPONSABILIDADE EXCLUSIVA DO COMPRADOR.\\\\n\\\\nCLÁUSULA QUINTA: As partes elegem o foro da comarca de {{LOJA_CIDADE}} para dirimir quaisquer dúvidas oriundas deste contrato.',\n  E'{{LOJA_CIDADE}}, {{DATA_CONTRATO}}\\\\n\\\\n\\\\n_______________________________\\\\nVENDEDORA: {{LOJA_RAZAO_SOCIAL}}\\\\n\\\\n\\\\n_______________________________\\\\nCOMPRADOR(A): {{CLIENTE_NOME}}\\\\nCPF: {{CLIENTE_CPF}}',\n  ARRAY['O EMPLACAMENTO É DE RESPONSABILIDADE EXCLUSIVA DO COMPRADOR.']::TEXT[]\n),\n(\n  'Contrato de Repasse',\n  'repasse',\n  true,\n  'CONTRATO DE REPASSE DE VEÍCULO',\n  E'Pelo presente instrumento particular, de um lado {{LOJA_RAZAO_SOCIAL}}, inscrita no CNPJ sob nº {{LOJA_CNPJ}}, com sede em {{LOJA_ENDERECO}}, doravante denominada CEDENTE, e de outro lado {{CLIENTE_NOME}}, portador(a) do CPF/CNPJ nº {{CLIENTE_CPF}}, com endereço em {{CLIENTE_ENDERECO}}, telefone {{CLIENTE_TELEFONE}}, doravante denominado(a) CESSIONÁRIO(A), firmam o presente contrato de repasse:\\\\n\\\\nVEÍCULO: {{VEICULO_MARCA}} {{VEICULO_MODELO}}\\\\nANO: {{VEICULO_ANO}}\\\\nCOR: {{VEICULO_COR}}\\\\nCHASSI: {{VEICULO_CHASSI}}\\\\nPLACA: {{VEICULO_PLACA}}\\\\n\\\\nVALOR DO REPASSE: {{VALOR_TOTAL}}',\n  E'CLÁUSULA PRIMEIRA: O CEDENTE transfere ao CESSIONÁRIO todos os direitos sobre o veículo acima descrito.\\\\n\\\\nCLÁUSULA SEGUNDA: O CESSIONÁRIO assume todas as responsabilidades legais e financeiras a partir da assinatura deste contrato.\\\\n\\\\nCLÁUSULA TERCEIRA: Eventuais débitos anteriores à data deste contrato são de responsabilidade do CEDENTE.\\\\n\\\\nCLÁUSULA QUARTA: As partes elegem o foro da comarca de {{LOJA_CIDADE}} para dirimir quaisquer dúvidas.',\n  E'{{LOJA_CIDADE}}, {{DATA_CONTRATO}}\\\\n\\\\n\\\\n_______________________________\\\\nCEDENTE: {{LOJA_RAZAO_SOCIAL}}\\\\n\\\\n\\\\n_______________________________\\\\nCESSIONÁRIO(A): {{CLIENTE_NOME}}',\n  ARRAY[]::TEXT[]\n);"}		apikey@lovable.dev	\N	\N
20251219230155	{"-- Adicionar campo vehicle_type na tabela vehicles\nALTER TABLE public.vehicles \nADD COLUMN IF NOT EXISTS vehicle_type TEXT DEFAULT 'carro' CHECK (vehicle_type IN ('carro', 'moto'));\n\n-- Adicionar campo engine_cc (cilindrada) para motos\nALTER TABLE public.vehicles \nADD COLUMN IF NOT EXISTS engine_cc INTEGER;"}		apikey@lovable.dev	\N	\N
20251219232655	{"-- Adicionar coluna reseller_id na tabela vehicles para vinculação com revendedores\nALTER TABLE public.vehicles \nADD COLUMN reseller_id uuid REFERENCES public.resellers(id) ON DELETE SET NULL;\n\n-- Criar índice para melhor performance nas buscas\nCREATE INDEX idx_vehicles_reseller_id ON public.vehicles(reseller_id);\n\n-- Comentário explicativo\nCOMMENT ON COLUMN public.vehicles.reseller_id IS 'ID do revendedor responsável pelo veículo (null = estoque da loja)';"}		apikey@lovable.dev	\N	\N
20251220191302	{"-- Allow admins to delete contracts\nCREATE POLICY \\"Admins can delete contracts\\"\nON public.contracts\nFOR DELETE\nUSING (has_role(auth.uid(), 'admin'::app_role));"}		apikey@lovable.dev	\N	\N
20260124052648	{"-- Tabela para contratos de consignação com revendedores\nCREATE TABLE public.reseller_consignment_contracts (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  vehicle_id UUID NOT NULL REFERENCES public.vehicles(id) ON DELETE CASCADE,\n  reseller_id UUID NOT NULL REFERENCES public.resellers(id) ON DELETE CASCADE,\n  store_id UUID NOT NULL REFERENCES public.stores(id) ON DELETE CASCADE,\n  \n  -- Valores do contrato\n  vehicle_cost NUMERIC NOT NULL, -- Valor que o revendedor paga (diferente do valor de venda ao público)\n  payment_type TEXT NOT NULL DEFAULT 'percentage', -- 'percentage' ou 'full'\n  \n  -- Para pagamento por porcentagem\n  upfront_percentage NUMERIC DEFAULT 0, -- % pago antecipadamente\n  upfront_amount NUMERIC DEFAULT 0, -- Valor calculado do upfront\n  remaining_percentage NUMERIC DEFAULT 0, -- % pago após venda\n  remaining_amount NUMERIC DEFAULT 0, -- Valor calculado do restante\n  \n  -- Para pagamento 100%\n  full_payment_amount NUMERIC DEFAULT 0,\n  \n  -- Controle de pagamentos\n  upfront_paid BOOLEAN DEFAULT false,\n  upfront_paid_at TIMESTAMPTZ,\n  remaining_paid BOOLEAN DEFAULT false,\n  remaining_paid_at TIMESTAMPTZ,\n  \n  -- Status do contrato\n  status TEXT NOT NULL DEFAULT 'ativo', -- ativo, quitado, cancelado\n  \n  -- Termos e observações\n  terms TEXT,\n  notes TEXT,\n  \n  -- Auditoria\n  created_by UUID REFERENCES auth.users(id),\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.reseller_consignment_contracts ENABLE ROW LEVEL SECURITY;\n\n-- Políticas RLS\nCREATE POLICY \\"Elevated users can manage consignment contracts\\"\nON public.reseller_consignment_contracts\nFOR ALL\nUSING (has_elevated_access(auth.uid()))\nWITH CHECK (has_elevated_access(auth.uid()));\n\nCREATE POLICY \\"View consignment contracts based on role\\"\nON public.reseller_consignment_contracts\nFOR SELECT\nUSING (\n  has_elevated_access(auth.uid()) OR\n  reseller_id IN (SELECT id FROM resellers WHERE user_id = auth.uid()) OR\n  store_id = get_user_store_id(auth.uid())\n);\n\n-- Trigger para atualizar updated_at\nCREATE TRIGGER update_reseller_consignment_contracts_updated_at\nBEFORE UPDATE ON public.reseller_consignment_contracts\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Adicionar coluna para identificar se usuário precisa trocar senha\nALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS must_change_password BOOLEAN DEFAULT false;"}		apikey@lovable.dev	\N	\N
20260302233723	{"-- Add 'vendedor' to app_role enum\nALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'vendedor';\n\n-- Create storage bucket for system backups\nINSERT INTO storage.buckets (id, name, public) VALUES ('system-backups', 'system-backups', false)\nON CONFLICT (id) DO NOTHING;\n\n-- Allow admins to manage backups\nCREATE POLICY \\"Admins can manage backups\\"\nON storage.objects\nFOR ALL\nUSING (bucket_id = 'system-backups' AND public.has_role(auth.uid(), 'admin'::app_role))\nWITH CHECK (bucket_id = 'system-backups' AND public.has_role(auth.uid(), 'admin'::app_role));\n\n-- Allow admins and managers to read backups  \nCREATE POLICY \\"Elevated users can read backups\\"\nON storage.objects\nFOR SELECT\nUSING (bucket_id = 'system-backups' AND public.has_elevated_access(auth.uid()));"}		apikey@lovable.dev	\N	\N
20260327164344	{"ALTER TABLE public.contracts ADD COLUMN IF NOT EXISTS created_by uuid;"}		apikey@lovable.dev	\N	\N
20260329103750	{"-- Restrict seller visibility on contracts to only their own sales while preserving admin/manager/revendedor access\nDROP POLICY IF EXISTS \\"View contracts based on role\\" ON public.contracts;\n\nCREATE POLICY \\"View contracts based on role\\"\nON public.contracts\nFOR SELECT\nTO authenticated\nUSING (\n  public.has_elevated_access(auth.uid())\n  OR created_by = auth.uid()\n  OR reseller_id IN (\n    SELECT r.id\n    FROM public.resellers r\n    WHERE r.user_id = auth.uid()\n  )\n);\n\n-- Allow sellers to update only contracts they created; admins/managers retain broader access\nDROP POLICY IF EXISTS \\"Admins can manage contracts\\" ON public.contracts;\n\nCREATE POLICY \\"Admins and sellers can update contracts\\"\nON public.contracts\nFOR UPDATE\nTO authenticated\nUSING (\n  public.has_elevated_access(auth.uid())\n  OR created_by = auth.uid()\n)\nWITH CHECK (\n  public.has_elevated_access(auth.uid())\n  OR created_by = auth.uid()\n);\n\n-- Allow sellers to create contracts directly as operator while preserving reseller flow\nDROP POLICY IF EXISTS \\"Create contracts\\" ON public.contracts;\n\nCREATE POLICY \\"Create contracts\\"\nON public.contracts\nFOR INSERT\nTO authenticated\nWITH CHECK (\n  public.has_elevated_access(auth.uid())\n  OR created_by = auth.uid()\n  OR reseller_id IN (\n    SELECT r.id\n    FROM public.resellers r\n    WHERE r.user_id = auth.uid()\n  )\n);"}		apikey@lovable.dev	\N	\N
20260329104544	{"-- Ensure sellers can see inventory from their store and only their own sales, while sales require manager/admin approval to finalize\nDROP POLICY IF EXISTS \\"View vehicles based on role\\" ON public.vehicles;\n\nCREATE POLICY \\"View vehicles based on role\\"\nON public.vehicles\nFOR SELECT\nTO authenticated\nUSING (\n  public.has_elevated_access(auth.uid())\n  OR store_id = public.get_user_store_id(auth.uid())\n  OR reseller_id IN (\n    SELECT r.id\n    FROM public.resellers r\n    WHERE r.user_id = auth.uid()\n  )\n);\n\nDROP POLICY IF EXISTS \\"View contracts based on role\\" ON public.contracts;\n\nCREATE POLICY \\"View contracts based on role\\"\nON public.contracts\nFOR SELECT\nTO authenticated\nUSING (\n  public.has_elevated_access(auth.uid())\n  OR created_by = auth.uid()\n  OR reseller_id IN (\n    SELECT r.id\n    FROM public.resellers r\n    WHERE r.user_id = auth.uid()\n  )\n);\n\nDROP POLICY IF EXISTS \\"Admins and sellers can update contracts\\" ON public.contracts;\n\nCREATE POLICY \\"Admins and sellers can update contracts\\"\nON public.contracts\nFOR UPDATE\nTO authenticated\nUSING (\n  public.has_elevated_access(auth.uid())\n  OR created_by = auth.uid()\n)\nWITH CHECK (\n  public.has_elevated_access(auth.uid())\n  OR created_by = auth.uid()\n);\n\nDROP POLICY IF EXISTS \\"Create contracts\\" ON public.contracts;\n\nCREATE POLICY \\"Create contracts\\"\nON public.contracts\nFOR INSERT\nTO authenticated\nWITH CHECK (\n  public.has_elevated_access(auth.uid())\n  OR created_by = auth.uid()\n  OR reseller_id IN (\n    SELECT r.id\n    FROM public.resellers r\n    WHERE r.user_id = auth.uid()\n  )\n);"}		apikey@lovable.dev	\N	\N
20260331161419	{"\nDROP POLICY IF EXISTS \\"Users can view own profile\\" ON public.profiles;\nCREATE POLICY \\"Users can view profiles based on role\\"\n  ON public.profiles FOR SELECT\n  TO authenticated\n  USING (\n    id = auth.uid() \n    OR has_elevated_access(auth.uid())\n  );\n"}		apikey@lovable.dev	\N	\N
20260705161311	{"-- 1. contract_templates: optional_clauses + vehicle_types\nALTER TABLE public.contract_templates\n  ADD COLUMN IF NOT EXISTS optional_clauses jsonb NOT NULL DEFAULT '[]'::jsonb,\n  ADD COLUMN IF NOT EXISTS vehicle_types text[] NOT NULL DEFAULT ARRAY['carro','moto']::text[];\n\n-- 2. vehicles: warranty + revision periods\nALTER TABLE public.vehicles\n  ADD COLUMN IF NOT EXISTS warranty_months integer,\n  ADD COLUMN IF NOT EXISTS revision_period_months integer,\n  ADD COLUMN IF NOT EXISTS revision_period_km integer;\n\n-- 3. contracts: snapshot das cláusulas ativas\nALTER TABLE public.contracts\n  ADD COLUMN IF NOT EXISTS active_clause_ids text[] NOT NULL DEFAULT ARRAY[]::text[];\n\n-- 4. Desativa modelos antigos (histórico preservado, contratos assinados continuam apontando)\nUPDATE public.contract_templates SET is_active = false WHERE is_active = true;\n\n-- 5. Seed do Contrato Mestre\nINSERT INTO public.contract_templates (\n  name, template_type, is_active, version, vehicle_types,\n  header_content, body_content, clauses_content, signature_content,\n  fixed_clauses, optional_clauses\n) VALUES (\n  'Contrato Mestre de Venda',\n  'generico',\n  true,\n  1,\n  ARRAY['carro','moto']::text[],\n  '[center][size:16][b]CONTRATO DE COMPRA E VENDA DE VEÍCULO[/b][/size][/center]\n\n[b]VENDEDORA:[/b] {{LOJA_RAZAO_SOCIAL}}, CNPJ {{LOJA_CNPJ}}, com sede em {{LOJA_ENDERECO}}, {{LOJA_CIDADE}}.\n\n[b]COMPRADOR(A):[/b] {{CLIENTE_NOME}}, CPF/CNPJ {{CLIENTE_CPF}}, residente em {{CLIENTE_ENDERECO}}, telefone {{CLIENTE_TELEFONE}}.',\n  '[b]OBJETO:[/b] O presente contrato tem por objeto a compra e venda do veículo abaixo descrito, livre e desembaraçado de quaisquer ônus:\n\nMarca/Modelo: {{VEICULO_MARCA}} {{VEICULO_MODELO}}\nAno: {{VEICULO_ANO}}   Cor: {{VEICULO_COR}}\nChassi: {{VEICULO_CHASSI}}   Placa: {{VEICULO_PLACA}}\nRenavam: {{VEICULO_RENAVAM}}\n\n[b]PREÇO E PAGAMENTO:[/b] O valor total ajustado é de R$ {{VALOR_TOTAL}}, pago na forma {{FORMA_PAGAMENTO}}. Entrada de R$ {{VALOR_ENTRADA}}, saldo em {{PARCELAS}} parcela(s) de R$ {{VALOR_PARCELA}}.',\n  '[b]CLÁUSULA 1ª — DA ENTREGA:[/b] O veículo é entregue no estado em que se encontra, tendo o(a) comprador(a) plena ciência de suas condições após vistoria prévia.\n\n[b]CLÁUSULA 2ª — DA DOCUMENTAÇÃO:[/b] A vendedora entrega o veículo com toda a documentação em dia. Fica a cargo do(a) comprador(a) providenciar a transferência junto ao órgão competente no prazo legal.\n\n[b]CLÁUSULA 3ª — DO FORO:[/b] Fica eleito o foro da comarca de {{LOJA_CIDADE}} para dirimir quaisquer questões oriundas deste contrato.',\n  '[center]{{LOJA_CIDADE}}, {{DATA_CONTRATO}}.[/center]\n\n_______________________________________\n[center]{{LOJA_RAZAO_SOCIAL}}\nVENDEDORA[/center]\n\n_______________________________________\n[center]{{CLIENTE_NOME}}\nCOMPRADOR(A)[/center]',\n  ARRAY[]::text[],\n  jsonb_build_array(\n    jsonb_build_object(\n      'id','emplacamento',\n      'label','Emplacamento por conta da loja',\n      'body_bbcode','[b]EMPLACAMENTO:[/b] A vendedora se compromete a providenciar o emplacamento do veículo, incluindo taxas de DETRAN, placa e primeiro licenciamento, sem custo adicional ao(à) comprador(a).',\n      'enabled_by_default', true,\n      'vehicle_types', jsonb_build_array('moto')\n    ),\n    jsonb_build_object(\n      'id','garantia',\n      'label','Garantia contratual',\n      'body_bbcode','[b]GARANTIA:[/b] O veículo possui garantia de {{GARANTIA_MESES}} meses contra defeitos de fabricação ou vícios ocultos, contados da data deste contrato, limitada aos itens do motor e câmbio, excluídos itens de desgaste natural.',\n      'enabled_by_default', true,\n      'vehicle_types', jsonb_build_array('carro','moto')\n    ),\n    jsonb_build_object(\n      'id','revisoes',\n      'label','Plano de revisões',\n      'body_bbcode','[b]REVISÕES:[/b] Para manutenção da garantia, o(a) comprador(a) deverá realizar revisões periódicas a cada {{REVISAO_MESES}} meses ou {{REVISAO_KM}} km — o que ocorrer primeiro — em oficina credenciada.',\n      'enabled_by_default', true,\n      'vehicle_types', jsonb_build_array('carro','moto')\n    ),\n    jsonb_build_object(\n      'id','transferencia',\n      'label','Transferência de titularidade por conta do comprador',\n      'body_bbcode','[b]TRANSFERÊNCIA:[/b] Fica sob responsabilidade exclusiva do(a) comprador(a) providenciar a transferência de titularidade junto ao DETRAN no prazo de 30 dias, arcando com todas as taxas envolvidas.',\n      'enabled_by_default', false,\n      'vehicle_types', jsonb_build_array('carro','moto')\n    ),\n    jsonb_build_object(\n      'id','seguro',\n      'label','Seguro opcional contratado',\n      'body_bbcode','[b]SEGURO:[/b] O(a) comprador(a) declara ter contratado seguro do veículo por conta própria, isentando a vendedora de qualquer responsabilidade por sinistros ocorridos após a entrega.',\n      'enabled_by_default', false,\n      'vehicle_types', jsonb_build_array('carro','moto')\n    ),\n    jsonb_build_object(\n      'id','acessorios',\n      'label','Acessórios inclusos',\n      'body_bbcode','[b]ACESSÓRIOS:[/b] Acompanham o veículo os acessórios originais de fábrica e itens listados no laudo de vistoria, sendo qualquer acessório adicional cobrado à parte.',\n      'enabled_by_default', false,\n      'vehicle_types', jsonb_build_array('carro','moto')\n    ),\n    jsonb_build_object(\n      'id','troca_devolucao',\n      'label','Política de troca/devolução',\n      'body_bbcode','[b]TROCA/DEVOLUÇÃO:[/b] O veículo, por se tratar de bem usado adquirido após vistoria, não admite devolução ou troca, salvo por vício oculto comprovado nos termos do Código de Defesa do Consumidor.',\n      'enabled_by_default', false,\n      'vehicle_types', jsonb_build_array('carro','moto')\n    )\n  )\n);"}	20260705161310_119719e9-7940-4d0c-af8e-3058894104df	apikey@lovable.dev	\N	\N
20260406131055	{"\nCREATE TABLE public.chassis_patterns (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  wmi_code text NOT NULL,\n  brand text NOT NULL,\n  vehicle_type text NOT NULL DEFAULT 'moto',\n  model_pattern text,\n  model_name text,\n  engine_cc integer,\n  fuel_type text DEFAULT 'Flex',\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.chassis_patterns ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \\"Authenticated users can view patterns\\"\nON public.chassis_patterns FOR SELECT\nTO authenticated\nUSING (true);\n\nCREATE POLICY \\"Admins can manage patterns\\"\nON public.chassis_patterns FOR ALL\nTO authenticated\nUSING (has_role(auth.uid(), 'admin'::app_role))\nWITH CHECK (has_role(auth.uid(), 'admin'::app_role));\n\nCREATE TRIGGER update_chassis_patterns_updated_at\nBEFORE UPDATE ON public.chassis_patterns\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Seed with existing hardcoded patterns\nINSERT INTO public.chassis_patterns (wmi_code, brand, vehicle_type, model_pattern, model_name, engine_cc, fuel_type) VALUES\n-- Honda motos\n('9C2', 'Honda', 'moto', 'KC08', 'CG 160 Titan', 162, 'Flex'),\n('9C2', 'Honda', 'moto', 'KC09', 'CG 160 Fan', 162, 'Flex'),\n('9C2', 'Honda', 'moto', 'KC10', 'CG 160 Start', 162, 'Flex'),\n('9C2', 'Honda', 'moto', 'KC16', 'CG 160 Cargo', 162, 'Flex'),\n('9C2', 'Honda', 'moto', 'JC75', 'Biz 125', 124, 'Flex'),\n('9C2', 'Honda', 'moto', 'JC81', 'Biz 110i', 109, 'Flex'),\n('9C2', 'Honda', 'moto', 'JC67', 'Pop 110i', 109, 'Flex'),\n('9C2', 'Honda', 'moto', 'KC13', 'NXR 160 Bros', 162, 'Flex'),\n('9C2', 'Honda', 'moto', 'PC44', 'CB 250F Twister', 249, 'Flex'),\n('9C2', 'Honda', 'moto', 'PC62', 'CB 300F Twister', 293, 'Flex'),\n('9C2', 'Honda', 'moto', 'FC50', 'PCX 160', 156, 'Flex'),\n('9C2', 'Honda', 'moto', 'JF60', 'Elite 125', 124, 'Flex'),\n('9C2', 'Honda', 'moto', 'MC41', 'CBR 650R', 649, 'F